-- 뉴스 트렌드: 기사마다 trend = 'sw'(소프트웨어 신기술 · AI 트렌드) | 'hw'(하드웨어 신기술) | NULL
-- 새 기사는 AI 요약이 정하고, 이미 있는 기사는 아래 키워드로 한 번 분류해요
ALTER TABLE news_items ADD COLUMN trend TEXT;
CREATE INDEX news_items_trend ON news_items(trend, published_at DESC) WHERE trend IS NOT NULL;
UPDATE news_items SET trend = 'hw' WHERE (lower(title) LIKE '%brain implant%' OR one_liner LIKE '%brain implant%') OR (lower(title) LIKE '%brain-computer%' OR one_liner LIKE '%brain-computer%') OR (lower(title) LIKE '%neuralink%' OR one_liner LIKE '%neuralink%') OR (lower(title) LIKE '%bci%' OR one_liner LIKE '%bci%') OR (lower(title) LIKE '%roadster%' OR one_liner LIKE '%roadster%') OR (lower(title) LIKE '%tesla%' OR one_liner LIKE '%tesla%') OR (lower(title) LIKE '%humanoid%' OR one_liner LIKE '%humanoid%') OR (lower(title) LIKE '%robot%' OR one_liner LIKE '%robot%') OR (lower(title) LIKE '%quantum%' OR one_liner LIKE '%quantum%') OR (lower(title) LIKE '%chip%' OR one_liner LIKE '%chip%') OR (lower(title) LIKE '%gpu%' OR one_liner LIKE '%gpu%') OR (lower(title) LIKE '% tpu%' OR one_liner LIKE '% tpu%') OR (lower(title) LIKE '%semiconductor%' OR one_liner LIKE '%semiconductor%') OR (lower(title) LIKE '%battery%' OR one_liner LIKE '%battery%') OR (lower(title) LIKE '%lidar%' OR one_liner LIKE '%lidar%') OR (lower(title) LIKE '%starship%' OR one_liner LIKE '%starship%') OR (lower(title) LIKE '%rocket%' OR one_liner LIKE '%rocket%') OR (lower(title) LIKE '%satellite%' OR one_liner LIKE '%satellite%') OR (lower(title) LIKE '%wearable%' OR one_liner LIKE '%wearable%') OR (lower(title) LIKE '%smart glasses%' OR one_liner LIKE '%smart glasses%') OR (lower(title) LIKE '%exoskeleton%' OR one_liner LIKE '%exoskeleton%') OR (lower(title) LIKE '%로봇%' OR one_liner LIKE '%로봇%') OR (lower(title) LIKE '%반도체%' OR one_liner LIKE '%반도체%') OR (lower(title) LIKE '%양자%' OR one_liner LIKE '%양자%') OR (lower(title) LIKE '%배터리%' OR one_liner LIKE '%배터리%') OR (lower(title) LIKE '%뇌 %' OR one_liner LIKE '%뇌 %') OR (lower(title) LIKE '%칩%' OR one_liner LIKE '%칩%') OR (lower(title) LIKE '%전기차%' OR one_liner LIKE '%전기차%') OR (lower(title) LIKE '%위성%' OR one_liner LIKE '%위성%') OR (lower(title) LIKE '%로켓%' OR one_liner LIKE '%로켓%') OR (lower(title) LIKE '%휴머노이드%' OR one_liner LIKE '%휴머노이드%');
UPDATE news_items SET trend = 'sw' WHERE trend IS NULL AND ((lower(title) LIKE '%jepa%' OR one_liner LIKE '%jepa%') OR (lower(title) LIKE '% rag %' OR one_liner LIKE '% rag %') OR (lower(title) LIKE '%retrieval%' OR one_liner LIKE '%retrieval%') OR (lower(title) LIKE '%agent%' OR one_liner LIKE '%agent%') OR (lower(title) LIKE '%llm%' OR one_liner LIKE '%llm%') OR (lower(title) LIKE '%language model%' OR one_liner LIKE '%language model%') OR (lower(title) LIKE '%transformer%' OR one_liner LIKE '%transformer%') OR (lower(title) LIKE '%diffusion%' OR one_liner LIKE '%diffusion%') OR (lower(title) LIKE '%open source%' OR one_liner LIKE '%open source%') OR (lower(title) LIKE '%open-source%' OR one_liner LIKE '%open-source%') OR (lower(title) LIKE '%framework%' OR one_liner LIKE '%framework%') OR (lower(title) LIKE '%compiler%' OR one_liner LIKE '%compiler%') OR (lower(title) LIKE '% rust%' OR one_liner LIKE '% rust%') OR (lower(title) LIKE '%webassembly%' OR one_liner LIKE '%webassembly%') OR (lower(title) LIKE '%kubernetes%' OR one_liner LIKE '%kubernetes%') OR (lower(title) LIKE '%inference%' OR one_liner LIKE '%inference%') OR (lower(title) LIKE '%fine-tun%' OR one_liner LIKE '%fine-tun%') OR (lower(title) LIKE '%reasoning%' OR one_liner LIKE '%reasoning%') OR (lower(title) LIKE '%benchmark%' OR one_liner LIKE '%benchmark%') OR (lower(title) LIKE '%sdk%' OR one_liner LIKE '%sdk%') OR (lower(title) LIKE '%mcp%' OR one_liner LIKE '%mcp%') OR (lower(title) LIKE '%에이전트%' OR one_liner LIKE '%에이전트%') OR (lower(title) LIKE '%언어 모델%' OR one_liner LIKE '%언어 모델%') OR (lower(title) LIKE '%오픈소스%' OR one_liner LIKE '%오픈소스%') OR (lower(title) LIKE '%프레임워크%' OR one_liner LIKE '%프레임워크%') OR (lower(title) LIKE '%추론%' OR one_liner LIKE '%추론%') OR (lower(title) LIKE '%모델 출시%' OR one_liner LIKE '%모델 출시%') OR (lower(title) LIKE '%코딩%' OR one_liner LIKE '%코딩%'));

