-- 정책 · 투자 · 소송 · 인사 기사는 빼요 (트렌드는 기술 그 자체만)
UPDATE news_items SET trend = NULL WHERE trend IS NOT NULL AND (lower(title) LIKE '%export%' OR lower(title) LIKE '%minister%' OR lower(title) LIKE '%court%' OR lower(title) LIKE '%arrest%' OR lower(title) LIKE '%sales%' OR lower(title) LIKE '%hiring%' OR lower(title) LIKE '% law%' OR lower(title) LIKE '%lawyer%' OR lower(title) LIKE '%tariff%' OR lower(title) LIKE '%sanction%' OR lower(title) LIKE '%regulat%' OR lower(title) LIKE '%stock%' OR lower(title) LIKE '%shares%' OR lower(title) LIKE '%invest%' OR lower(title) LIKE '%market%' OR lower(title) LIKE '%courts%' OR lower(title) LIKE '%white house%' OR lower(title) LIKE '%commerce%' OR lower(title) LIKE '%shortage%' OR lower(title) LIKE '%refund%' OR lower(title) LIKE '%rogue%' OR lower(title) LIKE '%says%' OR lower(title) LIKE '%ceo%');
